ee:message.ee:set-payload:
%dw 2.0 output application/java
/* Cosmetic CIE-to-Salesforce value differences, found during full-flow testing on 2026-08-19 and confirmed by Toshiv Shrivastava as wording-only (not a data/business distinction) / handled here on our side rather than as a Salesforce picklist change, since it's just punctuation/wording, not a new valid answer. Unmapped values pass through unchanged, so a value CIE hasn't sent yet (or a value that already matches) is untouched rather than silently dropped.
Add here, do NOT wait on a Salesforce picklist edit, when a mismatch turns out to be pure wording. Do escalate to Toshiv/Niranja instead when CIE has no valid equivalent at all (a real business/mapping decision) -- see the four items already resolved in that channel on 2026-08-19. */ var singlePicklistValueMap = { "Place not meant for human habitation (street, car, tent, park, uninhabitable RV/boat (no electricity/water)": "Place not meant for human habitation (street, car, tent, park, uninhabitable RV/boat, no electricity/water)" } var multiPicklistValueMap = { "Home purchase and housing financing counseling": "Home purchase and financing counseling" } fun normalizeSingle(value) = if (value == null) null else (singlePicklistValueMap[value] default value) fun normalizeMulti(value) = if (value == null) null else ((value splitBy ";") map ((token) -> multiPicklistValueMap[token] default token)) joinBy ";" --- { CIE_Assessment_ID__c: vars.matchRecord.sourceId, RecordTypeId: vars.housingAssessmentRecordTypeId, Member_PLI__c: vars.matchedMemberId default null, Case_PLI__c: vars.associatedCaseId default null, Current_Housing_Situation_PLI__c: vars.matchRecord.housingConcern, Current_Safety_Status_PLI__c: vars.matchRecord.safetyInCurrentSituation, Housing_Immediate_Threat_PLI__c: vars.matchRecord.immediateThreat, Housing_Need_Urgency_PLI__c: vars.matchRecord.immediacyOfNeed, Current_Housing_Type_PLI__c: normalizeSingle(vars.matchRecord.currentLivingSituation), Recent_Housing_Change_PLI__c: vars.matchRecord.livingSituationChanged30Days, Current_Stay_Duration_PLI__c: vars.matchRecord.timeLeftToStay, Homeless_Past_3_Years_PLI__c: vars.matchRecord.pastExperienceOfHomelessness, Homeless_Duration_3_Yrs_PLI__c: vars.matchRecord.monthsOfHomelessness, Last_Rental_Ownership_PLI__c: vars.matchRecord.lastTimeHadALease, Housing_Subsidy_Type_PLI__c: vars.matchRecord.subsidyForRentOrOwn, Housing_Loss_Risk_Timeframe_PLI__c: vars.matchRecord.riskOfLosingHousing, Housing_Expense_Tradeoff_PLI__c: vars.matchRecord.housingPrioritization, Housing_Financial_Barriers_PLI__c: vars.matchRecord.financialBarriers, Housing_Barriers_Ongoing_PLI__c: vars.matchRecord.pastOrOnGoingBarriers, Housing_Barriers_Current_PLI__c: vars.matchRecord.suddenEventBarriers, Housing_Support_Resources_PLI__c: vars.matchRecord.housingSupports, Prior_Resource_Use_PLI__c: vars.matchRecord.pastHousingResourceUtilization, Current_Resource_Use_PLI__c: vars.matchRecord.currentHousingResourceUtilization, Housing_Program_Knowledge_PLI__c: vars.matchRecord.housingResourceKnowledge, Housing_Budget_Comfort_PLI__c: vars.matchRecord.housingBudgetKnowledge, Housing_Resources_Needed_PLI__c: normalizeMulti(vars.matchRecord.desiredHousingResources) }

